const content = await figma.spec.getContent({ specNodeId: '8:2' });
return {
  title: content.title,
  totalLength: content.markdown.length,
  part1: content.markdown.substring(0, 25000)
};

const content = await figma.spec.getContent({ specNodeId: '8:2' });
return {
  part2: content.markdown.substring(24500)
};

const page = figma.currentPage;
const hero = page.findOne(n => n.name === 'Hero');
const portrait = page.findOne(n => n.name === 'Developer portrait');
const mark = page.findOne(n => n.name === 'exDesktop mark');

let avatarInfo = null;
if (portrait) {
  const imgNode = portrait.findOne(n => n.type === 'RECTANGLE' || n.fills?.some(f => f.type === 'IMAGE'));
  avatarInfo = {
    id: portrait.id,
    children: portrait.children.map(c => ({ id: c.id, name: c.name, type: c.type })),
    imgNodeId: imgNode ? imgNode.id : null
  };
}

return {
  heroId: hero ? hero.id : null,
  portrait: avatarInfo,
  markId: mark ? mark.id : null
};

const mark = await figma.getNodeByIdAsync('3:26');
const sunny = await figma.getNodeByIdAsync('3:117');
const markSvgBytes = await mark.exportAsync({ format: 'SVG' });
const sunnySvgBytes = await sunny.exportAsync({ format: 'SVG' });

return {
  markSvg: new TextDecoder().decode(markSvgBytes),
  sunnySvg: new TextDecoder().decode(sunnySvgBytes)
};

const mark = await figma.getNodeByIdAsync('3:26');
const sunny = await figma.getNodeByIdAsync('3:117');
const markSvgBytes = await mark.exportAsync({ format: 'SVG' });
const sunnySvgBytes = await sunny.exportAsync({ format: 'SVG' });

return {
  markSvgBase64: figma.base64Encode(markSvgBytes),
  sunnySvgBase64: figma.base64Encode(sunnySvgBytes)
};

const page = figma.currentPage;
const hero = page.findOne(n => n.name === 'Hero');
const decor = hero ? hero.findAll(n => n.name.toLowerCase().includes('flower') || n.name.toLowerCase().includes('clover')) : [];
const avatarNode = await figma.getNodeByIdAsync('3:118');

let avatarPngBase64 = null;
if (avatarNode) {
  const bytes = await avatarNode.exportAsync({ format: 'PNG' });
  avatarPngBase64 = figma.base64Encode(bytes);
}

const decorInfo = [];
for (const d of decor) {
  const bytes = await d.exportAsync({ format: 'SVG' });
  decorInfo.push({
    id: d.id,
    name: d.name,
    width: d.width,
    height: d.height,
    svgBase64: figma.base64Encode(bytes)
  });
}

return {
  avatarPngBase64Length: avatarPngBase64 ? avatarPngBase64.length : 0,
  decorCount: decorInfo.length,
  decorNames: decorInfo.map(d => d.name)
};

const page = figma.currentPage;
const iconNodes = page.findAll(n => n.name.toLowerCase().includes('icon') || n.name.toLowerCase().includes('symbol') || n.name.toLowerCase().includes('emblem'));

return iconNodes.map(n => ({
  id: n.id,
  name: n.name,
  parentName: n.parent ? n.parent.name : null,
  width: n.width,
  height: n.height
}));

const page = figma.currentPage;

// 1. Logo
const mark = page.findOne(n => n.name === 'exDesktop mark' && n.width === 44);
const markSvg = mark ? figma.base64Encode(await mark.exportAsync({ format: 'SVG' })) : null;

// 2. Sunny frame
const sunny = page.findOne(n => n.name === 'Rotating sunny frame');
const sunnySvg = sunny ? figma.base64Encode(await sunny.exportAsync({ format: 'SVG' })) : null;

// 3. Flower & Clover
const flower = page.findOne(n => n.name === 'Decorative flower');
const flowerSvg = flower ? figma.base64Encode(await flower.exportAsync({ format: 'SVG' })) : null;

const clover = page.findOne(n => n.name === 'Decorative clover');
const cloverSvg = clover ? figma.base64Encode(await clover.exportAsync({ format: 'SVG' })) : null;

// 4. Avatar
const avatar = page.findOne(n => n.name === 'METAWKA avatar');
const avatarPng = avatar ? figma.base64Encode(await avatar.exportAsync({ format: 'PNG' })) : null;

// 5. Question emblem in FAQ heading
const questionEmblem = page.findOne(n => n.name === 'Question emblem');
const questionEmblemSvg = questionEmblem ? figma.base64Encode(await questionEmblem.exportAsync({ format: 'SVG' })) : null;

return {
  markSvg,
  sunnySvg,
  flowerSvg,
  cloverSvg,
  avatarPngLength: avatarPng ? avatarPng.length : 0,
  avatarPng,
  questionEmblemSvg
};

const page = figma.currentPage;

const mark = page.findOne(n => n.name === 'exDesktop mark' && n.width === 44);
const markSvg = mark ? figma.base64Encode(await mark.exportAsync({ format: 'SVG' })) : null;

const sunny = page.findOne(n => n.name === 'Rotating sunny frame');
const sunnySvg = sunny ? figma.base64Encode(await sunny.exportAsync({ format: 'SVG' })) : null;

const flower = page.findOne(n => n.name === 'Decorative flower');
const flowerSvg = flower ? figma.base64Encode(await flower.exportAsync({ format: 'SVG' })) : null;

const clover = page.findOne(n => n.name === 'Decorative clover');
const cloverSvg = clover ? figma.base64Encode(await clover.exportAsync({ format: 'SVG' })) : null;

const questionEmblem = page.findOne(n => n.name === 'Question emblem');
const questionEmblemSvg = questionEmblem ? figma.base64Encode(await questionEmblem.exportAsync({ format: 'SVG' })) : null;

return {
  markSvg,
  sunnySvg,
  flowerSvg,
  cloverSvg,
  questionEmblemSvg
};

const iconIds = {
  sun: '3:38',
  moon: '3:56',
  menu: '16:192',
  close: '16:717',
  download: '3:108',
  code: '3:41',
  check: '3:101',
  arrow_right: '3:168',
  arrow_external: '3:156',
  arrow_down: '3:205',
  arrow_left: '3:239',
  terminal: '3:147',
  github: '3:160',
  telegram: '3:367',
  chat: '3:371',
  changelog: '3:375',
  mail: '3:379',
  help: '3:195',
  tune: '16:62',
  shield: '16:68',
  work: '16:94'
};

const result = {};
for (const [key, id] of Object.entries(iconIds)) {
  const node = await figma.getNodeByIdAsync(id);
  if (node) {
    const bytes = await node.exportAsync({ format: 'SVG' });
    result[key] = figma.base64Encode(bytes);
  }
}

return result;

const avatar = await figma.getNodeByIdAsync('3:118');
if (avatar) {
  const svgBytes = await avatar.exportAsync({ format: 'SVG' });
  return {
    svg: figma.base64Encode(svgBytes)
  };
}
return null;

const avatar = await figma.getNodeByIdAsync('3:118');
if (avatar && 'vectorPaths' in avatar) {
  return {
    paths: avatar.vectorPaths,
    width: avatar.width,
    height: avatar.height
  };
}
return null;

