interface MobileMenuProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigate: (path: string) => void;
}

export const MobileMenu: React.FC<MobileMenuProps> = ({
  isOpen,
  onClose,
  onNavigate
}) => {
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
          onClose();
        }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => {
        document.body.style.overflow = '';
        window.removeEventListener('keydown', handleKeyDown);
      };
    } else {
      document.body.style.overflow = '';
    }
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleItemClick = (e: React.MouseEvent, path: string) => {
    e.preventDefault();
    onNavigate(path);
    onClose();
  };

  return (
    <div className="mobile-menu-overlay" onClick={onClose}>
      <div
        className="mobile-menu-panel"
        ref={panelRef}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Мобильная навигация"
      >
        {/* Top Header */}
        <div className="mobile-menu-header">
          <div className="menu-brand">
            <img src="/assets/markSvg.svg" alt="" width={36} height={36} />
            <span className="menu-brand-text">exDesktop</span>
          </div>
          <button
            onClick={onClose}
            className="menu-close-btn"
            aria-label="Закрыть мобильное меню"
          >
            <Icon name="close" size={24} color="var(--text-primary)" />
          </button>
        </div>

        {/* Navigation list */}
        <nav className="mobile-menu-nav">
          <a
            href="/"
            onClick={(e) => handleItemClick(e, '/')}
            className="menu-item"
          >
            Главная
          </a>
          <a
            href="/#preview"
            onClick={(e) => handleItemClick(e, '/#preview')}
            className="menu-item"
          >
            Превью
          </a>
          <a
            href="/#features"
            onClick={(e) => handleItemClick(e, '/#features')}
            className="menu-item"
          >
            Возможности
          </a>
          <a
            href="/#installation"
            onClick={(e) => handleItemClick(e, '/#installation')}
            className="menu-item"
          >
            Установка
          </a>
          <a
            href="/#roadmap"
            onClick={(e) => handleItemClick(e, '/#roadmap')}
            className="menu-item"
          >
            Roadmap
          </a>
          <a
            href="/faq"
            onClick={(e) => handleItemClick(e, '/faq')}
            className="menu-item"
          >
            FAQ
          </a>
          <a
            href={SITE_LINKS.github}
            target="_blank"
            rel="noopener noreferrer"
            className="menu-item external"
          >
            <span>GitHub</span>
            <Icon name="arrow_external" size={20} color="var(--text-secondary)" />
          </a>
        </nav>

        {/* CTA Button */}
        <div className="mobile-menu-cta">
          <a
            href={SITE_LINKS.download}
            target="_blank"
            rel="noopener noreferrer"
            className="pill-button primary"
            style={{ width: '100%' }}
          >
            <Icon name="download" size={22} color="var(--text-on-accent)" />
            <span>Скачать exDesktop</span>
          </a>
        </div>
      </div>

      <style>{`
        .mobile-menu-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-color: rgba(0, 0, 0, 0.65);
          backdrop-filter: blur(8px);
          z-index: 1000;
